        throw new TypeError("data must be an object of columns");
    const terms = termsOf(parsed, Object.keys(data), rhs);
    if (options.intercept !== undefined)
        terms.intercept = options.intercept;
    const frameNames = [...terms.variables, ...(options.extraVariables ?? []).filter((v) => !terms.variables.includes(v))];
    const frameOptions = {};
    if (options.levels !== undefined)
        frameOptions.levels = options.levels;
    if (options.weights !== undefined)
        frameOptions.weights = options.weights;
    if (options.dropUnusedLevels !== undefined)
        frameOptions.dropUnusedLevels = options.dropUnusedLevels;
    const frame = modelFrame(data, frameNames, frameOptions);
    const vars = frame.variables;
    const nr = frame.rows.length;
    // the terms that get columns, and the code of each variable in them
    const used = terms.terms.map((_, j) => j !== terms.responseTerm);
    // the contrasts given: a warning for each name that is not a variable of the formula (in the order of the object),
    // an error for a numeric variable
